INSERT INTO enigmas (type, difficulty, theme, format, question, lore_text, choices, answer, explanation, active) VALUES
('daily', 'very_easy', 'grecque', 'qcm', 'Quel général perse commandait les forces terrestres lors de la bataille de Platées en 479 av. J.-C. ?', 'Après la retraite du Grand Roi, un homme de confiance resta sur le sol grec, portant le poids d''un empire sur ses épaules. On dit qu''il dormait sous des tentes ornées d''or et de pourpre, entouré d''une garde d''élite. Son destin allait sceller celui de toute l''expédition.', '["Mardonios","Artabaze","Mégabaze","Hydarnes"]'::jsonb, 'Mardonios', 'Mardonios, beau-frère de Xerxès, commanda l''armée perse laissée en Grèce après la retraite du roi. Il fut tué à Platées en 479 av. J.-C., ce qui provoqua la débandade perse.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel roi perse lança la première grande expédition punitive contre les cités grecques continentales vers 490 av. J.-C. ?', 'Des messagers portant terre et eau parcouraient les routes de l''empire, exigeant la soumission au nom du maître du monde. Les cités grecques devaient choisir : plier le genou ou affronter la fureur d''un roi qui se disait roi des rois. Certaines plièrent ; d''autres choisirent le fer.', '["Darius Ier","Cyrus le Grand","Cambyse II","Xerxès Ier"]'::jsonb, 'Darius Ier', 'Darius Ier organisa l''expédition de 490 av. J.-C. pour punir Athènes et Érétrie, qui avaient soutenu la révolte ionienne. C''est lors de cette campagne qu''eut lieu la bataille du 13 septembre 490.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Où l''amiral grec Thémistocle remporta-t-il sa grande victoire navale en 480 av. J.-C. ?', 'Entre une île sacrée et le continent, les eaux étroites se transformèrent en piège mortel. Les rameurs grecs avaient faim, peur et peu de sommeil — mais un stratège leur avait promis que le terrain lui-même se battrait à leurs côtés. Le roi barbare regardait depuis son trône de pierre la mer avaler son invincible flotte.', '["Salamine","Mycale","Artémision","Lemnos"]'::jsonb, 'Salamine', 'La bataille de Salamine eut lieu en septembre 480 av. J.-C. dans le détroit entre l''île de Salamine et l''Attique. La flotte grecque, sous l''impulsion de Thémistocle, détruisit une grande partie de la flotte perse.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel archonte athénien, vers 594 av. J.-C., abolit l''esclavage pour dettes (seisachtheia) et réforma les classes censitaires ?', 'La cité respirait sous le joug des dettes. Des hommes libres portaient sur leur peau la marque de la servitude, vendus pour quelques médimnes de grain. Un législateur, dit-on, porta ce fardeau comme Atlas porte le ciel — et le souleva.', '["Dracon","Solon","Pisistrate","Miltiade"]'::jsonb, 'Solon', 'Solon, archonte éponyme vers 594 av. J.-C., promulgua la seisachtheia (secouement des fardeaux), abolissant l''esclavage pour dettes, et réorganisa la cité en quatre classes censitaires (pentacosiomédimnoi, hippeis, zeugites, thètes).', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Comment appelait-on l''assemblée de tous les citoyens athéniens qui votait les lois et décidait de la guerre ?', 'Sur la colline de la Pnyx, sous le ciel ouvert d''Attique, des milliers de voix pouvaient faire basculer le destin d''une cité entière. Aucun mur, aucun toit ne séparait les délibérants du regard des dieux.', '["La Boulè","L''Héliée","L''Ecclesia","L''Aréopage"]'::jsonb, 'L''Ecclesia', 'L''Ecclesia (assemblée du peuple) réunissait tous les citoyens athéniens mâles adultes sur la Pnyx. Elle votait les lois, déclarait la guerre, ratifiait les traités et élisait les stratèges.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel nom portait l''assemblée des citoyens spartiates, composée des guerriers en armes ?', 'Une fois par mois au moins, la plaine résonnait d''un seul bruit : pas de discours interminables, pas de vote à main levée comptée — seulement l''acclamation ou le silence, rugissement ou néant. On y décidait de la guerre et de la paix, sans jamais que la palabre ne l''emporte sur la décision.', '["L''Ecclésia","La Boulè","L''Apella","L''Héliée"]'::jsonb, 'L''Apella', 'L''Apella était l''assemblée des citoyens spartiates (Spartiates de plein droit) ; elle votait par acclamation sur les propositions soumises par la Gérousie et les éphores, sans pouvoir en modifier les termes.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel philosophe de Milet affirmait que l''eau est le principe originel de toutes choses ?', 'Au bord de la mer Égée, un sage de Milet contemplait les flots et croyait y lire le secret du cosmos. Avant lui, les dieux expliquaient le monde ; après lui, la raison tenterait de le faire.', '["Anaximandre","Thalès","Anaximène","Empédocle"]'::jsonb, 'Thalès', 'Thalès de Milet (vers 625-545 av. J.-C.) est le premier à avoir proposé une explication naturaliste du cosmos : l''eau (ὕδωρ) serait l''arkhè, le principe fondateur de toute réalité.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Selon Anaximène, quel élément primordial, en se raréfiant ou en se condensant, engendre toutes les choses ?', 'Troisième grand sage de Milet, il chercha un principe plus subtil que ses prédécesseurs : invisible, omniprésent, il enveloppe le monde entier comme une âme enveloppe le corps.', '["Le feu","La terre","L''air","L''eau"]'::jsonb, 'L''air', 'Anaximène (vers 585-525 av. J.-C.) posait l''air (ἀήρ) comme principe universel : sa condensation produit le vent, les nuages, la terre ; sa raréfaction produit le feu.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel savant d''Alexandrie a mesuré la circonférence de la Terre avec une précision remarquable ?', 'À Syène, le soleil frappe le fond d''un puits sans projeter d''ombre. À Alexandrie, il incline ses rayons. Un homme a su lire dans cet écart le tour complet de notre monde.', '["Ératosthène","Hipparque","Aristarque","Ctésibios"]'::jsonb, 'Ératosthène', 'Ératosthène de Cyrène (v. 276-194 av. J.-C.), directeur de la Bibliothèque d''Alexandrie, calcula la circonférence terrestre en mesurant l''angle de l''ombre à Alexandrie le jour du solstice d''été, obtenant environ 40 000 km — une valeur très proche de la réalité.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Comment appelle-t-on l''ouvrage en treize volumes dans lequel Euclide expose les fondements de la géométrie ?', 'Dans les salles studieuses d''Alexandrie, des scribes copient un texte devenu presque sacré. Pendant deux millénaires, aucun géomètre ne pourra se prétendre formé sans l''avoir parcouru de la première à la dernière proposition.', '["Les Éléments","L''Almageste","La Syntaxe","Les Coniques"]'::jsonb, 'Les Éléments', 'Les Éléments d''Euclide (v. 300 av. J.-C.) constituent l''un des ouvrages scientifiques les plus diffusés de l''histoire : treize livres couvrant géométrie plane, arithmétique, proportions et géométrie dans l''espace.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel dieu guérisseur accueillait les malades dans son sanctuaire pour la nuit sacrée d''incubation ?', 'Le pèlerin s''allongeait sur une peau de bête dans l''obscurité du temple. Il attendait le sommeil, espérant que le fils d''Apollon lui apparaîtrait en rêve, accompagné de ses serpents, pour lui révéler le remède à son mal.', '["Hermès","Héphaïstos","Poséidon","Asclépios"]'::jsonb, 'Asclépios', 'Asclépios, dieu de la médecine, était vénéré dans des sanctuaires appelés Asclépieia (Épidaure, Cos, Pergame). L''incubation — sommeil rituel dans le temple — permettait au dieu d''envoyer des rêves guérisseurs.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel arbre sacré donnait ses oracles dans le sanctuaire de Dodone, en Épire ?', 'Au fond du nord-ouest de la Grèce, loin du fracas des cités, un sanctuaire chuchotait ses prophéties depuis des siècles. Les prêtres écoutaient le bruissement des feuilles et le tintement de bassins de bronze suspendus, cherchant la voix de Zeus.', '["L''olivier","Le cyprès","Le laurier","Le chêne"]'::jsonb, 'Le chêne', 'À Dodone, l''oracle le plus ancien de Grèce, les prêtres interprétaient le bruissement du chêne sacré de Zeus. Homère y fait déjà allusion dans l''Iliade.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel ordre architectural se reconnaît à son chapiteau orné de volutes enroulées ?', 'Les bâtisseurs grecs ne choisissaient pas leurs colonnes au hasard. Chaque ordre portait une grammaire visuelle précise, une signature gravée dans la pierre qui parlait de proportion et d''identité civique.', '["Dorique","Ionique","Corinthien","Toscan"]'::jsonb, 'Ionique', 'L''ordre ionique se distingue par ses chapiteaux à volutes (spirales). Le dorique est austère et sans décoration, le corinthien arbore des feuilles d''acanthe.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Aristophane est le maître incontesté de quel genre théâtral grec ?', 'Sur la scène d''Athènes, ce genre faisait rire aux larmes : on y déguisait les politiciens en saucissiers, on y faisait voler des hommes sur des scarabées géants. Le masque grimaçant régnait sans partage.', '["La tragédie","L''épopée","La comédie","Le dithyrambe"]'::jsonb, 'La comédie', 'Aristophane (v. 446–386 av. J.-C.) est le principal représentant de la comédie ancienne athénienne. Ses pièces (Les Nuées, Les Grenouilles, Lysistrata) raillaient hommes politiques et philosophes.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quelle grande bataille de 301 av. J.-C. scella le sort des Diadoques et mit fin aux ambitions d''un roi borgne ?', 'Les successeurs d''Alexandre s''étaient déchirés pendant deux décennies. Ce jour-là, sur une plaine de Phrygie, les éléphants de guerre chargèrent et le destin d''un empire bascula dans la poussière.', '["Bataille de Gaza","Bataille d''Ipsos","Bataille de Corinthe","Bataille de Raphia"]'::jsonb, 'Bataille d''Ipsos', 'La bataille d''Ipsos (301 av. J.-C.) en Phrygie opposa Antigone le Borgne et son fils Démétrios à la coalition de Lysimaque, Séleukos et Cassandre. Antigone y fut tué et son empire démembré.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Comment appelait-on le grec commun parlé dans tout le monde hellénistique après Alexandre ?', 'Des marchands de Memphis aux philosophes de Babylone, une même langue circulait comme une monnaie invisible. Elle unissait des peuples que nulle armée n''aurait pu souder aussi durablement.', '["Dialecte attique","Grec dorien","Koinè","Grec ionien"]'::jsonb, 'Koinè', 'La koinè (du grec koïnè dialektos, « langue commune ») est la forme de grec standardisée qui s''imposa dans les royaumes hellénistiques comme langue administrative, commerciale et littéraire.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quelle merveille architecturale, construite sur une île à l''entrée d''un grand port égyptien, guidait les navires de nuit ?', 'Des flammes visibles à des kilomètres en mer, un miroir de bronze renvoyant leur éclat vers l''horizon — les marins disaient qu''aucun cap dangereux n''était aussi bien gardé. L''ingéniosité hellénistique avait fait du danger une promesse de salut.', '["Le Colosse de Rhodes","Le Phare d''Alexandrie","La Tour des Vents d''Athènes","Le phare de Carthage"]'::jsonb, 'Le Phare d''Alexandrie', 'Le Phare d''Alexandrie, construit sur l''île de Pharos vers 280 av. J.-C. sous Ptolémée II, est considéré comme l''une des Sept Merveilles du monde antique. Il pouvait atteindre 100 à 130 mètres de hauteur.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quelle petite pièce de monnaie valait un sixième de drachme dans la Grèce antique ?', 'Sur l''agora d''Athènes, les marchands pesaient chaque pièce avec soin. La plus humble d''entre elles changeait de main des dizaines de fois par jour — pour un bol d''olives, un verre de vin coupé, ou l''entrée d''un bain public.', '["Le statère","L''obole","Le talent","Le tétradrachme"]'::jsonb, 'L''obole', 'L''obole valait 1/6 de drachme. C''était la monnaie du quotidien pour les Athéniens modestes, suffisante pour payer un repas frugal ou le salaire d''un demi-jour de travail non qualifié.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel animal était frappé sur les tétradrachmes d''Athènes, au revers de la tête d''Athéna ?', 'La monnaie athénienne circulait jusqu''aux confins de la Méditerranée. Sur une face, le regard perçant de la déesse ; sur l''autre, une créature nocturne associée à la sagesse, dont la silhouette suffit à identifier l''origine de la pièce sans même lire la légende.', '["L''aigle","Le dauphin","La chouette","Le serpent"]'::jsonb, 'La chouette', 'Les tétradrachmes athéniens portaient la chouette (glaukos), oiseau sacré d''Athéna, avec une branche d''olivier et le croissant de lune. Ces pièces étaient si réputées qu''on les appelait simplement « les chouettes ».', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Comment appelait-on le lieu de réunion au centre de la cité grecque, à la fois marché, tribunal et espace politique ?', 'Au cœur de chaque polis, un espace ouvert animé dès l''aube par les cris des marchands et les débats des citoyens. Philosophes, plaideurs et charlatans s''y croisaient, sous le regard indifférent des statues de héros fondateurs.', '["Le stade","L''agora","L''acropole","Le prytanée"]'::jsonb, 'L''agora', 'L''agora était l''espace public central de la cité grecque, servant à la fois de marché, de lieu de réunion politique et de forum judiciaire. À Athènes, l''agora du Céramique en était l''exemple le plus célèbre.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel était le nom du grand bouclier rond en bronze porté par le fantassin grec ?', 'Sur le champ de bataille, la ligne des guerriers avançait au rythme des flûtes. Chaque homme portait un disque de bois et de bronze si lourd qu''il protégeait autant son voisin de gauche que lui-même — abandon du rang synonyme de déshonneur absolu.', '["Xiphos","Hoplon","Sarisse","Kopis"]'::jsonb, 'Hoplon', 'L''hoplon (ou aspis) était le bouclier circulaire d''environ 90 cm de diamètre, en bois renforcé de bronze, caractéristique de l''hoplite grec. Sa forme et sa taille imposaient une discipline collective.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Comment appelait-on le fantassin lourdement armé qui formait l''épine dorsale des armées grecques ?', 'Il ne portait pas la robe du savant ni le manteau du philosophe. Casqué de bronze, cuirassé, lance et bouclier en main, il incarnait la vertu civique faite chair — l''ordre social et la survie de la cité reposaient sur son courage au rang.', '["Peltaste","Hoplite","Toxote","Hypaspiste"]'::jsonb, 'Hoplite', 'L''hoplite était le soldat d''infanterie lourde grec, équipé du hoplon, d''une lance (doru) et d''une épée courte. Il formait la phalange et constituait le cœur des armées des cités-États du VIIe au IVe siècle av. J.-C.', TRUE),
('daily', 'very_easy', 'grecque', 'qcm', 'Quel type de navire de guerre grec, à cinquante rameurs, précéda la grande trirème de combat ?', 'Avant que les flottes de guerre ne se couvrent de rostres d''airain et de rangs de rameurs superposés, un navire plus ancien sillonnait déjà les mers égéennes. Cinquante bras plongeaient leurs avirons à l''unisson, propulsant la coque vers les rivages ennemis ou vers le commerce lointain.', '["Pentécontère","Liburne","Biremme","Phasélos"]'::jsonb, 'Pentécontère', 'La pentécontère était un navire de guerre archaïque à cinquante rameurs disposés sur un seul rang. Elle fut largement utilisée avant que la trirème ne la supplante comme principale unité de combat naval au Ve siècle av. J.-C.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel stratagème Thémistocle utilisa-t-il pour attirer la flotte perse dans le détroit de Salamine ?', 'Un messager secret traversa les lignes ennemies dans la nuit, portant des mots soigneusement choisis. Les Perses crurent tenir leur chance de détruire la flotte grecque d''un seul coup, sans savoir qu''ils marchaient vers un guet-apens ourdi de bout en bout. La ruse, plus que le bronze, allait décider du sort de l''Occident.', '["Il fit croire que les Grecs allaient fuir pour forcer un engagement nocturne","Il incendia ses propres navires pour bloquer le détroit","Il négocia une trêve puis attaqua par surprise à l''aube","Il convainquit des transfuges perses de saboter les ancres ennemies"]'::jsonb, 'Il fit croire que les Grecs allaient fuir pour forcer un engagement nocturne', 'Thémistocle envoya son esclave Sicinnos avertir Xerxès que les Grecs s''apprêtaient à prendre la fuite, poussant le roi à encercler le détroit de nuit et à engager la bataille dans un espace trop étroit pour sa supériorité numérique.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quelle cité ionienne déclencha la grande révolte contre la domination perse vers 499 av. J.-C. ?', 'Sur la côte d''Asie Mineure, une cité marchande et intellectuelle choisit de briser ses chaînes dorées. Son tyran avait trop promis au Grand Roi et trop peu livré ; la honte et l''ambition firent le reste. L''incendie qui s''ensuivit alluma une guerre qui brûlerait pendant deux générations.', '["Milet","Éphèse","Sardes","Halicarnasse"]'::jsonb, 'Milet', 'La révolte ionienne (499-494 av. J.-C.) fut lancée par Milet, sous l''impulsion d''Aristagoras, son tyran. Milet fut finalement détruite par les Perses en 494 av. J.-C. après la défaite navale de Ladé.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel nom portait le gouverneur perse d''une province, représentant direct du Grand Roi ?', 'Dans les palais de brique cuite et de cèdre, ces hommes régnaient en maîtres sur des territoires aussi vastes que des royaumes entiers. Ils levaient l''impôt, rendaient la justice, levaient des troupes — mais une seule lettre du roi pouvait les destituer ou les condamner à mort. Leur splendeur n''était que le reflet de la lumière royale.', '["Satrape","Basileus","Polémarque","Chiliarque"]'::jsonb, 'Satrape', 'Le satrape était le gouverneur d''une satrapie, province de l''empire achéménide. Il administrait le territoire au nom du Grand Roi, collectait les tributs et commandait les forces locales.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Lors de quelle bataille navale les Grecs retardèrent-ils la flotte perse en 480 av. J.-C., avant de se replier ?', 'Face au cap rocheux, les proues se heurtèrent pendant trois jours sans vainqueur définitif. Chaque nuit, les deux flottes comptaient leurs morts et réparaient leurs rames brisées. La nouvelle qui arriva du sud mit fin aux combats avant que la mer ne tranche.', '["Artémision","Mycale","Cnide","Égospotamos"]'::jsonb, 'Artémision', 'La bataille d''Artémision (480 av. J.-C.), au large de l''Eubée, fut livrée simultanément aux combats terrestres du même été. Les Grecs se replièrent en apprenant le résultat des combats qui les avaient débordés sur leur flanc.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel tribunal populaire athénien, composé de plusieurs centaines de jurés tirés au sort, jugeait les affaires civiles et pénales majeures ?', 'Des urnes de bronze, des jetons de bois, des mains calleuses de citoyens déposant leur verdict en silence. La justice n''avait ni visage de marbre ni sceptre doré — elle ressemblait à n''importe quel homme libre de la cité.', '["L''Aréopage","L''Héliée","La Boulè","Le Thesmothète"]'::jsonb, 'L''Héliée', 'L''Héliée était le grand tribunal populaire d''Athènes, composé de 6 000 héliastes (jurés) tirés au sort annuellement parmi les citoyens de plus de 30 ans. Ses sections jugeaient la majorité des causes importantes.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Pisistrate s''empara du pouvoir à Athènes à trois reprises. Comment appelle-t-on ce type de régime qu''il incarna ?', 'Il n''abolit pas les lois de son prédécesseur — il les laissa en place et gouverna dans leur ombre. Les Athéniens vivaient sous des règles qu''ils reconnaissaient, mais la main qui guidait la cité n''était pas celle qu''ils avaient choisie.', '["Oligarchie","Tyrannie","Aristocratie","Théocratie"]'::jsonb, 'Tyrannie', 'Pisistrate exerça la tyrannie — au sens grec du terme, un pouvoir personnel non héréditaire conquis par la force. Il régna à trois reprises (vers 561, 556 et 546-528 av. J.-C.) tout en maintenant formellement les institutions soloniennes.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel réformateur, associé à Périclès, dépouilla l''Aréopage de la plupart de ses pouvoirs politiques en 462 av. J.-C. ?', 'L''antique conseil des sages gardiens veillait depuis des siècles sur la cité comme une main de pierre. Il fallut l''audace d''un homme résolu pour desserrer ces doigts — et cet homme ne vécut guère longtemps après son geste.', '["Thémistocle","Cimon","Ephialte","Aristide"]'::jsonb, 'Ephialte', 'Ephialte, en 462/461 av. J.-C., fit voter des lois transférant les attributions politiques de l''Aréopage à la Boulè, à l''Héliée et à l''Ecclesia. Il fut assassiné peu après dans des circonstances jamais élucidées.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel statut désignait les populations libres non-citoyennes qui vivaient autour de Sparte et servaient d''artisans et de commerçants ?', 'Ils forgeaient les boucliers, tannaient le cuir, fondaient le bronze — tout ce que les guerriers dédaignaient de leurs mains. Libres, mais sans voix dans la cité. On les tolérait, on les encadrait, on pouvait les enrôler en temps de guerre. Leur rôle était indispensable ; leur invisibilité, totale.', '["Les métèques","Les pénestes","Les périèques","Les thètes"]'::jsonb, 'Les périèques', 'Les périèques (« ceux qui habitent alentour ») étaient des hommes libres vivant dans les bourgades de Laconie et de Messénie ; ils pratiquaient l''artisanat et le commerce, payaient des impôts et servaient dans l''armée, mais n''avaient aucun droit politique à Sparte.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quelle pratique secrète permettait à de jeunes Spartiates d''éliminer des hilotes isolés durant la nuit ?', 'Armés seulement d''un couteau, ils partaient seuls dans les ténèbres de la campagne laconienne, sans vivres, sans flambeau. L''ordre venait d''en haut, la cible était précise : quiconque, parmi les serfs de la terre, se montrait trop fort, trop influent, trop susceptible de lever la tête.', '["La xénélasie","La krypteia","La locheia","La syssitie"]'::jsonb, 'La krypteia', 'La krypteia était une institution spartiate par laquelle de jeunes hommes sélectionnés vivaient cachés dans la campagne et pouvaient tuer des hilotes jugés dangereux ; Plutarque et Aristote en témoignent comme d''un outil de terreur sociale.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Parménide d''Élée soutenait que le changement et le mouvement sont des illusions. Que seul existe vraiment, selon lui ?', 'Dans la cité d''Élée, au sud de l''Italie, un philosophe osa contredire les sens : ce que nous voyons bouger et changer ne serait qu''un voile trompeur sur une vérité éternelle et immobile.', '["Le devenir perpétuel","L''Être unique et immuable","Les quatre éléments","Le vide infini"]'::jsonb, 'L''Être unique et immuable', 'Parménide (vers 515-450 av. J.-C.) posait dans son Poème que seul l''Être (τὸ ἐόν) est réel : un, éternel, immobile et indivisible. Le non-être ne peut ni être pensé ni exister.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel paradoxe de Zénon d''Élée met en scène un héros grec incapable de rattraper une tortue ?', 'Un disciple fidèle de Parménide forgeait des arguments aussi tranchants que des lames pour prouver l''impossibilité du mouvement. Ses adversaires ne pouvaient réfuter ses raisonnements, et pourtant leurs jambes marchaient.', '["Le paradoxe de la flèche","Le paradoxe d''Achille et la tortue","Le paradoxe du stade","Le paradoxe du grain de millet"]'::jsonb, 'Le paradoxe d''Achille et la tortue', 'Zénon d''Élée (vers 490-430 av. J.-C.) argumentait qu''Achille, le guerrier le plus rapide, ne peut jamais rattraper une tortue : chaque fois qu''il atteint l''endroit où elle était, elle a légèrement avancé, à l''infini.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel savant grec du IIIe siècle av. J.-C. est considéré comme le fondateur de la botanique ?', 'Son maître avait classé les animaux avec une minutie implacable. Lui tourna son regard vers les racines, les feuilles et les graines, rédigeant des traités si exhaustifs que les jardins de médicaments lui devaient autant qu''aux dieux guérisseurs.', '["Théophraste","Dioscoride","Anaxagore","Straton de Lampsaque"]'::jsonb, 'Théophraste', 'Théophraste d''Érèse (v. 371-287 av. J.-C.), successeur d''Aristote à la tête du Lycée, rédigea Historia Plantarum et De Causis Plantarum, deux traités qui fondent la botanique comme discipline scientifique autonome.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel astronome grec du IIe siècle av. J.-C. dressa le premier catalogue stellaire précis et découvrit la précession des équinoxes ?', 'De son observatoire de Rhodes, il scrutait le ciel nuit après nuit, consignant chaque étoile avec une méthode inégalée. En comparant ses notes aux archives babyloniennes, il remarqua que les constellations s''étaient légèrement déplacées sur fond d''éternité.', '["Hipparque de Nicée","Aristarque de Samos","Callimaque","Sosigène"]'::jsonb, 'Hipparque de Nicée', 'Hipparque de Nicée (v. 190-120 av. J.-C.) composa un catalogue d''environ 850 étoiles avec leurs coordonnées et magnitude, et découvrit la précession des équinoxes en comparant ses observations aux données babyloniennes antérieures.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel sacrifice massif consistait à immoler cent bœufs lors des grandes fêtes civiques ?', 'La fumée montait au-dessus de l''Acropole, portant vers les dieux l''odeur des chairs brûlées. Des centaines d''animaux avaient été conduits en procession solennelle. La générosité d''une cité envers ses dieux se mesurait à l''ampleur de cet offrande.', '["L''hécatombe","Le sphagion","La thysia","L''enagismata"]'::jsonb, 'L''hécatombe', 'L''hécatombe (du grec hekaton, cent, et bous, bœuf) désigne le sacrifice de cent bœufs. Elle était offerte lors des grandes fêtes panhelléniques et civiques, notamment aux Panathénées.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'L''orphisme enseignait que l''âme humaine était prisonnière d''un cycle de réincarnations. Quel nom donnait-on à ce cycle ?', 'Des tablettes d''or minuscules, glissées dans les tombes, portaient des instructions pour l''âme du défunt : quelles sources éviter, quelles paroles prononcer aux gardiens de l''au-delà. Les initiés espéraient briser l''enchaînement éternel et rejoindre les bienheureux.', '["L''Elysée","Le Tartare","La roue de la Génèse","Le Léthé"]'::jsonb, 'La roue de la Génèse', 'L''orphisme appelait le cycle des réincarnations ''trochos geneseos'' (roue de la naissance ou de la Génèse). Les tablettes d''or orphiques (Thurii, IVe s. av. J.-C.) guident l''âme pour en sortir.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Le culte des héros grecs impliquait des offrandes versées dans des fosses ou sur des tombeaux. Comment appelait-on ces rites funèbres offerts aux morts héroïques ?', 'La nuit tombée, le prêtre s''agenouillait près d''un creux dans la terre et versait du vin, du miel et du sang vers le bas plutôt que vers le ciel. Les héros n''étaient pas des dieux, mais leur puissance dormante dans le sol protégeait la cité et ses récoltes.', '["Libations olympiennes","Enagismata","Splagchnoptia","Aparche"]'::jsonb, 'Enagismata', 'Les enagismata (''offrandes chthoniennes'') désignent les sacrifices et libations versés dans des fosses pour les héros et les morts. Contrairement aux sacrifices olympiens, l''offrande allait vers le bas, vers les puissances souterraines.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Le ''Canon'' de Polyclète définissait les proportions idéales du corps humain. Quelle statue en est l''illustration la plus célèbre ?', 'Polyclète ne sculpta pas seulement du bronze : il codifiait une loi. Son traité théorique, le Canon, établissait des rapports mathématiques entre chaque partie du corps, comme si la beauté obéissait à un ordre secret.', '["L''Apollon du Belvédère","Le Doryphore","L''Hermès de Praxitèle","Le Discobole"]'::jsonb, 'Le Doryphore', 'Le Doryphore (Porte-Lance), sculpté vers 450–440 av. J.-C., est la manifestation plastique du Canon de Polyclète, qui fixait le rapport idéal tête/corps à 1/7.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Dans la céramique grecque, la technique à figures noires consiste à peindre les silhouettes en argile noire sur fond de quelle couleur ?', 'Sur ces vases qui traversèrent la Méditerranée entière, les héros combattaient, les dieux festoyaient. Le potier traçait ses lignes avec une précision presque rituelle, incisant les détails à la pointe dans l''argile encore fraîche.', '["Blanc","Rouge","Ocre clair (couleur naturelle de l''argile)","Bleu"]'::jsonb, 'Ocre clair (couleur naturelle de l''argile)', 'Dans la technique à figures noires (VIIe–Ve s. av. J.-C.), les silhouettes sont peintes en engobe noir sur le fond rouge-ocre naturel de l''argile attique. Les détails intérieurs sont incisés.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Les Grandes Dionysies étaient un festival athénien dédié à Dionysos. En quelle saison avaient-elles lieu ?', 'Athènes entière suspendait ses affaires : prisonniers relâchés pour l''occasion, dettes mises en attente, étrangers admis dans la cité. Pendant plusieurs jours, la scène était le cœur battant de la polis.', '["En été (juillet)","À l''automne (octobre)","En hiver (décembre)","Au printemps (mars-avril)"]'::jsonb, 'Au printemps (mars-avril)', 'Les Grandes (ou Cités) Dionysies se tenaient à Athènes en Élaphébolion (mars-avril), au printemps, en l''honneur de Dionysos Éleuthérios. C''est là que tragédies et comédies s''affrontaient.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel général diadoque fonda la dynastie qui régna sur la Syrie, la Mésopotamie et la Perse pendant plus de deux siècles ?', 'Après des années à servir fidèlement le Conquérant, cet homme reçut en partage les terres les plus vastes — et les plus difficiles à tenir. Il bâtit des cités, déplaça des peuples, et forgea un empire à l''image de sa propre ambition froide et méthodique.', '["Antigone","Lysimaque","Séleukos","Cassandre"]'::jsonb, 'Séleukos', 'Séleukos Ier Nikator fonda la dynastie séleucide vers 305 av. J.-C. après s''être emparé de Babylone. Son empire s''étendait de l''Anatolie à l''Inde et dura jusqu''en 63 av. J.-C.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quelle institution hellénistique d''Alexandrie réunissait savants, poètes et médecins sous le patronage royal, précurseur de nos académies ?', 'Des hommes venus de Cyrène, d''Athènes ou de Syène mangeaient à la table du roi, débattaient de géométrie et de poésie entre des colonnes de marbre blanc. Nul autre palais du monde n''avait jamais concentré autant de savoir sous un seul toit.', '["Le Lycée","Le Mouseion","L''Académie","Le Sérapéion"]'::jsonb, 'Le Mouseion', 'Le Mouseion (Musée) d''Alexandrie, fondé sous les premiers Ptolémées, était un centre de recherche royal où les savants recevaient une pension et vivaient en communauté. Il était étroitement lié à la Grande Bibliothèque.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quelle cité d''Asie Mineure devint, sous les Attalides, un grand foyer culturel rival d''Alexandrie, célèbre pour son parchemin ?', 'Juchée sur une acropole dominant une riche plaine, cette ville abrita une bibliothèque rivale et un art baroque d''une violence presque mystique. Ses rois se voulaient défenseurs de la civilisation grecque contre les Barbares.', '["Éphèse","Pergame","Smyrne","Milet"]'::jsonb, 'Pergame', 'Pergame, capitale des rois Attalides, développa une bibliothèque de 200 000 volumes et donna son nom au parchemin (pergamène). L''Autel de Pergame et le Grand Frise de Gigantomacie illustrent l''art hellénistique à son apogée.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Comment appelait-on les étrangers résidant légalement à Athènes, qui payaient des taxes mais n''avaient pas le droit de vote ?', 'Ils construisaient des temples, tenaient les meilleures boutiques, enseignaient la rhétorique et commandaient des navires marchands. Certains amassèrent des fortunes considérables — mais jamais un siège à l''Assemblée. Leur statut juridique les maintenait dans une zone d''entre-deux, ni citoyens ni esclaves.', '["Les hilotes","Les perioèques","Les métèques","Les thètes"]'::jsonb, 'Les métèques', 'Les métèques (metoikoi) étaient des étrangers domiciliés à Athènes qui devaient payer un impôt spécifique (le métoikion) et se placer sous la tutelle d''un citoyen garant (prostate). Ils participaient à l''économie mais étaient exclus de la vie politique.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel nom portait le banquet athénien où l''on buvait du vin mélangé et débattait de philosophie ou d''amour ?', 'Les coussins sont disposés, les couronnes de lierre tressées. Un serviteur verse le vin dans le grand cratère, le mêle d''eau selon la règle de la modération. Ce soir, les invités allongés décideront d''un thème et chacun devra y contribuer — en vers si possible.', '["Le gymnase","L''andrôn","Le symposion","Le komos"]'::jsonb, 'Le symposion', 'Le symposion (littéralement « boire ensemble ») était un banquet exclusivement masculin où citoyens aisés se réunissaient après le repas pour boire du vin mélangé, écouter de la musique, réciter des poèmes et débattre. Le Banquet de Platon en est la description la plus célèbre.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel terme grec désignait une colonie fondée par une cité-mère, qui envoyait des colons établir une nouvelle polis indépendante ?', 'Sur le quai du Pirée, le prêtre éteint le feu sacré de la cité — il sera rallumé sur la nouvelle terre. Les colons emportent la terre de leurs aïeux, les dieux tutélaires, et les coutumes de la métropole. Mais la nouvelle fondation sera libre : une cité-sœur, non une province.', '["L''empórion","L''apoikia","La koinè","La stasis"]'::jsonb, 'L''apoikia', 'L''apoikia (« maison loin de chez soi ») était la colonie grecque fondée par une métropole qui envoyait des citoyens excédentaires fonder une nouvelle cité autonome. Entre VIIIe et VIe s. av. J.-C., les Grecs colonisèrent ainsi les rivages de Méditerranée et de la mer Noire.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Quel général athénien du IVe siècle révolutionna la guerre en réformant l''armement et la tactique des soldats légers ?', 'Fils d''un cordonnier, il grimpa au sommet de l''art militaire grec par son seul génie. Il comprit que la légèreté et la vitesse pouvaient vaincre l''alourdissement du métal — et ses hommes apprirent à harceler, esquiver et frapper avant que l''adversaire ne pût répondre.', '["Conon","Iphicrate","Agésilas","Timothée"]'::jsonb, 'Iphicrate', 'Iphicrate (418–353 av. J.-C.) réforma l''armement des peltastes athéniens : lances plus longues, boucliers plus légers, bottines éponymiques (iphicratides). En 390, ses peltastes anéantirent à Léchaion un mora spartiate — victoire retentissante pour l''infanterie légère.', TRUE),
('daily', 'easy', 'grecque', 'qcm', 'Les peltastes tiraient leur nom de quel équipement distinctif ?', 'Ni la lourde armure du citoyen-soldat ni la nudité du simple paysan — ces combattants occupaient un espace intermédiaire, rapides comme des renards entre les lignes. Leur arme de jet volait avant même que l''ennemi ne les atteignît, et leur protection légère leur permettait de disparaître aussi vite qu''ils avaient surgi.', '["Leur javelot à courroie","Leur bouclier en osier ou cuir (peltè)","Leur casque à cimier coloré","Leurs bottines à lanières (krepides)"]'::jsonb, 'Leur bouclier en osier ou cuir (peltè)', 'Le peltaste doit son nom à la peltè, un petit bouclier léger en osier recouvert de cuir ou de peau de chèvre, sans la rigidité de bronze de l''hoplon. Originaires de Thrace, ces soldats légers armés de javelots devinrent essentiels aux armées grecques du Ve-IVe siècle.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel exploit d''ingénierie militaire Xerxès réalisa-t-il pour franchir le détroit entre l''Europe et l''Asie en 480 av. J.-C. ?', 'On raconte que lorsque la première construction fut emportée par une tempête, le roi ordonna de fouetter la mer rebelle et d''y jeter des fers. Une telle démesure ne pouvait qu''appeler une réponse du destin. Pourtant, la seconde tentative tint, et des centaines de milliers d''hommes marchèrent sur les flots.', '["Il construisit un double pont de bateaux amarrés en ligne","Il fit creuser un canal à travers le promontoire de l''Athos","Il fit construire des radeaux géants de bois de cèdre liés au fond","Il utilisa des galères pontées comme pontons flottants fixes"]'::jsonb, 'Il construisit un double pont de bateaux amarrés en ligne', 'Xerxès fit construire deux ponts de bateaux (pentecontères et trières) sur l''Hellespont, reliés par des câbles de lin et de papyrus. Un premier pont fut détruit par une tempête ; le second permit le passage de l''armée en 480 av. J.-C.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel amiral grec commandait la flotte lors de la bataille de Mycale en 479 av. J.-C. ?', 'Sur les rivages d''Asie, la guerre reprit à l''endroit même où elle avait commencé, comme si le destin voulait boucler un cercle. Les Ioniens, enfermés dans leur camp fortifié, hésitèrent entre leur maître et leur sang. Un signal de feu, dit-on, traversa la mer avant même que la victoire soit connue.', '["Léotychidas","Cimon","Xanthippe","Eurybiade"]'::jsonb, 'Léotychidas', 'La bataille de Mycale (août 479 av. J.-C.) fut livrée sur le cap Mycale en Ionie. La flotte et l''armée grecques étaient commandées par le roi spartiate Léotychidas, qui vainquit les Perses à terre après que ceux-ci eurent tiré leurs navires sur la plage.', TRUE),
('daily', 'medium', 'grecque', 'free', 'Quel général spartiate commandait les forces grecques coalisées à Platées en 479 av. J.-C. ?', 'Un régent de sang royal, tuteur d''un roi trop jeune pour porter le sceptre, prit la tête d''une alliance fragile où Athènes et Sparte se surveillaient du coin de l''œil. Il imposa une discipline de fer aux contingents indisciplinés et attendit le bon moment avec une patience que ses alliés prirent pour de la lâcheté. La victoire lui fut totale — et sa fin, tragique.', NULL, 'Pausanias', 'Pausanias, régent de Sparte et neveu de Léonidas, commanda la coalition panhellénique à Platées. Sa victoire mit fin à la présence militaire perse en Grèce continentale, mais il fut plus tard accusé de trahison et mourut emmûré dans un temple.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel nom porte l''antique conseil aristocratique athénien siégeant sur une colline rocheuse à l''ouest de l''Acropole, dont les pouvoirs furent réduits en 462 av. J.-C. ?', 'On dit que des puissances nocturnes venaient y déposer leurs querelles, bien avant que les hommes n''y portent leurs causes. La colline gardait une mémoire plus longue que celle des cités — et plus froide.', '["La Pnyx","L''Aréopage","Le Céramique","L''Agora"]'::jsonb, 'L''Aréopage', 'L''Aréopage (colline d''Arès) était le plus ancien conseil d''Athènes, composé des anciens archontes. Avant 462, il exerçait une tutelle générale sur la constitution. Ephialte lui ôta ces prérogatives politiques, lui laissant principalement les affaires de meurtre.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Sous Périclès, les citoyens pauvres purent siéger à l''Héliée et aux magistratures grâce à l''instauration de quel dispositif financier ?', 'La vertu civique ne devait pas rester l''apanage des riches. En ouvrant la porte du tribunal à l''homme sans fortune, la cité pariait que la sagesse n''était pas une affaire de patrimoine — et cela changeait tout.', '["La mistophorie","La liturgie","L''eisphorè","La trierarchie"]'::jsonb, 'La mistophorie', 'La mistophorie (paiement des fonctions publiques) fut introduite sous Périclès : les héliastes, puis les membres de la Boulè et d''autres magistrats reçurent une indemnité journalière (misthos), permettant aux citoyens sans fortune de s''acquitter de leurs devoirs civiques.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel amiral spartiate imposa l''hégémonie de Sparte sur la mer Égée après 404 av. J.-C., grâce à une flotte financée par la Perse ?', 'On racontait qu''il avait fait forger un sceau unique, qu''il redistribuait l''or des vaincus à ses propres réseaux, que les oligarques des cités lui devaient leur trône. Ses ennemis le disaient corruptible ; ses partisans, inévitable. Quand Sparte le rappela et le condamna, il alla se placer sous la protection du Grand Roi lui-même.', '["Brasidas","Callicratidas","Gylippos","Lysandre"]'::jsonb, 'Lysandre', 'Lysandre (mort en 395 av. J.-C.) fut le navarque spartiate qui, grâce aux subsides perses de Cyrus le Jeune, bâtit la flotte qui écrasa Athènes à Aigos-Potamos (405 av. J.-C.) ; il instaura ensuite des décarchies pro-spartiates dans les cités soumises.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel roi spartiate domina la politique grecque dans la première moitié du IVe siècle av. J.-C. et mena de longues campagnes en Asie Mineure ?', 'Boiteux de naissance, il avait dû surmonter les réticences de sa propre cité avant de régner. Mais sur le champ de bataille, nul ne contestait son génie. Des années durant, ses armées parcoururent les satrapies comme jadis les Dix-Mille, ravivant le rêve d''un monde grec libéré du joug perse.', '["Agésilas II","Cléombrote I","Archidamos II","Pausanias"]'::jsonb, 'Agésilas II', 'Agésilas II (445–360 av. J.-C.) régna sur Sparte pendant environ quarante ans ; il mena des campagnes victorieuses en Asie Mineure dès 396 av. J.-C. avant d''être rappelé par la guerre de Corinthe, et resta l''incarnation de l''idéal guerrier spartiate tardif.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Empédocle d''Agrigente proposa quatre « racines » de toutes choses. Quelles sont-elles ?', 'Philosophe, médecin et, dit-on, thaumaturge, il parcourait la Sicile en habits de pourpre, convaincu d''être un dieu exilé parmi les mortels. Dans ses poèmes, il voyait le cosmos comme un éternel combat entre union et séparation.', '["Eau, air, feu, éther","Eau, terre, feu, air","Feu, lumière, ténèbres, vide","Eau, terre, bois, métal"]'::jsonb, 'Eau, terre, feu, air', 'Empédocle d''Agrigente (vers 495-435 av. J.-C.) posait quatre « racines » (ῥιζώματα) : l''eau, la terre, le feu et l''air, gouvernées par deux forces cosmiques antagonistes, l''Amour (φιλία) et la Discorde (νεῖκος).', TRUE),
('daily', 'medium', 'grecque', 'free', 'Anaxagore postulait un principe intellect pur qui mit l''univers en mouvement. Quel est le nom grec de ce principe ?', 'Venu de Clazomènes en Ionie, ce sage s''installa à Athènes et devint l''ami de Périclès. Poursuivi pour impiété car il affirmait que le Soleil était une pierre ardente, il dut fuir la cité. Avant sa fuite, il avait nommé la force ordonnant le cosmos d''un seul mot souverain.', NULL, 'Noûs', 'Anaxagore de Clazomènes (vers 500-428 av. J.-C.) posait le Noûs (νοῦς, « Esprit » ou « Intelligence ») comme principe immatériel et pur ayant imprimé le mouvement rotatif initial au cosmos, sans se mêler à la matière.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Par quelle méthode Ératosthène calcula-t-il la distance angulaire entre Alexandrie et Syène ?', 'Nul besoin de parcourir les déserts en chameau : des arpenteurs royaux — les bématistes — avaient déjà compté leurs pas entre les deux villes. Il ne restait qu''à lire l''angle de l''ombre au moment précis où le ciel le permettait.', '["En mesurant l''angle de l''ombre d''un gnomon au solstice d''été","En comparant les phases lunaires simultanées","En mesurant la parallaxe de Mars","En observant les éclipses solaires depuis deux points"]'::jsonb, 'En mesurant l''angle de l''ombre d''un gnomon au solstice d''été', 'Ératosthène planta un gnomon à Alexandrie et mesura l''angle de son ombre au solstice d''été (environ 7,2°, soit 1/50e du cercle). En multipliant la distance Alexandrie-Syène par 50, il obtint la circonférence terrestre.', TRUE),
('daily', 'medium', 'grecque', 'free', 'Quel contemporain et rival d''Hérophile, cofondateur de l''école de médecine d''Alexandrie, se spécialisa dans l''étude du système cardio-vasculaire et distingua veines et artères ?', 'À ses côtés dans les salles de dissection alexandrines, un autre médecin poursuivait l''enquête anatomique. Là où son confrère avait sondé le cerveau, lui se penchait sur le cœur et les vaisseaux, cherchant à comprendre ce qui pulse et ce qui nourrit.', NULL, 'Érasistrate', 'Érasistrate de Céos (v. 304-250 av. J.-C.) travailla avec Hérophile à Alexandrie et distingua clairement veines et artères ; il nia que les artères contiennent du sang, les croyant porteuses d''air (pneuma) — erreur productive qui stimula des siècles de débat médical.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel postulat géométrique des Éléments d''Euclide fut contesté pendant deux millénaires avant de donner naissance à des géométries alternatives ?', 'Les quatre premiers postulats semblaient coulés de source. Mais le cinquième avait quelque chose d''étrange, de trop chargé — comme si l''édifice entier reposait en secret sur une fondation que le maître lui-même n''osait pas tout à fait regarder en face.', '["Le postulat des parallèles","Le postulat du cercle","Le postulat du point","Le postulat de la droite infinie"]'::jsonb, 'Le postulat des parallèles', 'Le cinquième postulat d''Euclide (par un point extérieur à une droite, il passe une unique parallèle) fut jugé trop complexe pour un axiome. Sa contestation mena, au XIXe siècle, aux géométries non-euclidiennes de Lobatchevski et Riemann.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'L''oracle de Trophonios, en Béotie, imposait à ses consultants une épreuve physique unique. Laquelle ?', 'Le pèlerin se préparait pendant des jours par des purifications et des sacrifices. Puis venait le moment redouté : il devait s''engager seul dans une fissure de la terre et laisser l''obscurité l''engloutir. Ceux qui remontaient disaient ne jamais avoir retrouvé le sourire.', '["Boire une eau amnésiante et dormir trois nuits dans le temple","S''immerger dans un lac souterrain et prononcer des formules sacrées","Descendre dans une crypte souterraine en rampant les pieds en premier","Jeûner quarante jours puis gravir la montagne sacrée les yeux bandés"]'::jsonb, 'Descendre dans une crypte souterraine en rampant les pieds en premier', 'Pausanias (IX, 39) décrit la descente dans le manteion de Trophonios à Lébadée : le consultant s''allongeait sur le dos, glissait les pieds dans une ouverture étroite et était littéralement aspiré vers le bas. L''expérience était si terrifiante que l''expression ''avoir consulté Trophonios'' signifiait avoir perdu le sourire.', TRUE),
('daily', 'medium', 'grecque', 'free', 'Quel poète légendaire, fondateur mythique de l''orphisme, était censé avoir charmé les bêtes sauvages et les pierres par son chant ?', 'Sa lyre résonnait d''une telle harmonie que les rochers se déplaçaient et les fleuves s''arrêtaient. On lui attribuait des hymnes sacrés et des cosmogonies secrètes, transmis de maître à disciple dans les cercles initiatiques. Même les Muses pleurèrent sa mort, démembré par des femmes en transe.', NULL, 'Orphée', 'Orphée, figure semi-légendaire de Thrace, est le fondateur mythique de l''orphisme. On lui attribuait les Hymnes Orphiques et des tablettes initiatiques. Son démembrement par les ménades thraces est attesté dès Eschyle.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'L''ordre corinthien, le plus orné des trois ordres grecs, tire son chapiteau de la forme stylisée de quelle plante ?', 'La légende attribuait son invention à l''architecte Callimaque qui, passant près d''une tombe, aurait aperçu un panier entouré de végétation sauvage. La beauté du hasard devint alors règle universelle.', '["Le laurier","La vigne","L''acanthe","L''olivier"]'::jsonb, 'L''acanthe', 'Le chapiteau corinthien est orné de feuilles d''acanthe stylisées (Acanthus spinosus). Vitruve attribue son invention à Callimaque au Ve s. av. J.-C. C''est l''ordre le plus tardif et le plus décoratif.', TRUE),
('daily', 'medium', 'grecque', 'free', 'Quel sculpteur du IVe siècle av. J.-C., rival de Scopas, est célèbre pour son Hermès portant Dionysos enfant, retrouvé à Olympie ?', 'Son ciseau transformait le marbre en chair souple, presque vivante. On disait que ses statues penchaient légèrement, dans une pose déhanchée que les historiens de l''art appelleront plus tard la ''ligne serpentine''. À Cnide, sa représentation d''une déesse nue fit scandale et gloire.', NULL, 'Praxitèle', 'Praxitèle (v. 400–330 av. J.-C.) sculpta l''Hermès d''Olympie (v. 330 av. J.-C.) et l''Aphrodite de Cnide, première statue féminine nue monumentale. Son style lyrique contraste avec le classicisme de Polyclète.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Dans la technique à figures rouges, qui remplace la technique à figures noires vers 530 av. J.-C., que représente le fond du vase ?', 'Un potier du Kerameikos eut un jour l''idée d''inverser tout le procédé. Ce qui était clair devint sombre, ce qui était sombre devint lumineux. Cette révolution silencieuse allait conquérir toutes les cités grecques en moins d''une génération.', '["Le fond est peint en blanc","Le fond est peint en noir","Le fond est laissé en argile naturelle rouge-ocre","Le fond est peint en bleu"]'::jsonb, 'Le fond est peint en noir', 'Dans la technique à figures rouges, le fond est recouvert d''engobe noir tandis que les figures gardent la couleur naturelle rouge de l''argile attique. Les détails sont peints au pinceau, non incisés.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel était le principal minerai extrait des mines du Laurion, dont l''exploitation finança la flotte athénienne au Ve siècle av. J.-C. ?', 'Sous les collines du cap Sounion, des milliers de silhouettes courbées creusaient sans relâche dans l''obscurité. Le sol recrachait un métal brillant qui allait transformer la destinée de la cité — non par magie, mais par la volonté d''un stratège qui convainquit l''Assemblée de ne pas partager le butin.', '["L''or","Le cuivre","L''étain","L''argent"]'::jsonb, 'L''argent', 'Les mines d''argent du Laurion (Attique) produisaient le métal qui frappait les tétradrachmes athéniens. En 483 av. J.-C., Thémistocle convainquit les Athéniens d''utiliser leur revenu exceptionnel pour construire 200 trières, flotte décisive à Salamine.', TRUE),
('daily', 'medium', 'grecque', 'free', 'Quel détroit ou mer était le principal axe d''importation du blé depuis les comptoirs pontiques vers Athènes au IVe siècle av. J.-C. ?', 'Les négociants athéniens le savaient : sans ce passage étroit entre deux mers, la cité mourrait de faim en moins d''un an. Des escadres entières y patrouillaient pour protéger les convois chargés de grain scythe. Contrôler ces eaux, c''était tenir Athènes par le ventre.', NULL, 'Bosphore', 'Le Bosphore (Bosporos Cimmérien inclus) était l''axe stratégique du commerce céréalier athénien : le blé de Crimée et des cités pontiques transitait par le Bosphore de Thrace, raison pour laquelle Athènes y maintenait une influence diplomatique et militaire constante.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quel auteur grec a rédigé l''Anabase, récit de la retraite des mercenaires grecs à travers la Perse ?', 'Élève d''un philosophe athénien, il choisit pourtant la voie des armes plutôt que celle de la pensée pure. Quand les généraux furent assassinés et que le désespoir gagnait les rangs, il se leva devant les soldats rassemblés, leur parla de courage et de devoir — puis saisit le stylet pour immortaliser cette odyssée dans la prose la plus claire de l''Antiquité.', '["Thucydide","Polybe","Xénophon","Arrien"]'::jsonb, 'Xénophon', 'Xénophon d''Athènes (vers 430–355 av. J.-C.) participa à l''expédition des Dix Mille en tant que simple volontaire, puis fut élu stratège après le massacre des généraux. Son Anabase relate cette retraite en sept livres et reste un document militaire et littéraire de premier ordre.', TRUE),
('daily', 'medium', 'grecque', 'qcm', 'Quelle machine de siège, utilisant la tension de cordes torsadées, permit de lancer des projectiles lourds lors des sièges grecs et macédoniens ?', 'Devant les hauts murs de pierre, les généraux savaient qu''aucune charge frontale ne suffirait. Les ingénieurs calculaient les angles, tendaient les fibres avec une précision quasi rituelle — et soudain la muraille qui semblait éternelle commençait à craindre pour la première fois la colère humaine.', '["Bélier couvert (tortue)","Oxybèle","Catapulte à torsion (palintone)","Tour de siège (hélépole)"]'::jsonb, 'Catapulte à torsion (palintone)', 'La catapulte à torsion (palintone ou lithobolos) utilisait l''énergie emmagasinée dans des faisceaux de cordes ou de tendons torsadés pour propulser des boulets de pierre. Perfectionnée sous Philippe II et Alexandre le Grand, elle révolutionna la poliorcétique grecque au IVe siècle av. J.-C.', TRUE),
('daily', 'medium', 'grecque', 'free', 'Quel était le cri lancé par les Dix Mille quand ils aperçurent enfin la mer au terme de leur longue marche ?', 'Des mois de marche, de batailles, de faim et de gel dans les montagnes. Puis, depuis une crête d''Anatolie, les hommes du premier rang se mirent à hurler — et les rangs suivants reprirent le cri, pensant d''abord à une attaque. Mais c''était l''annonce de la délivrance, la fin de l''exil au cœur d''un empire hostile.', NULL, 'Thalassa', 'Selon l''Anabase de Xénophon (IV, 7), les soldats aperçurent la mer Noire depuis le mont Thèchès et crièrent ''Thalassa ! Thalassa !'' (La mer ! La mer !). Ce moment est l''un des plus célèbres de la littérature grecque antique.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Quelle reine, vassale de l''empire perse, commanda ses propres navires à la bataille de Salamine en 480 av. J.-C. ?', 'Dans le fracas des éperons et des rames brisées, une figure singulière manœuvrait avec une audace qui stupéfia les deux camps. Xerxès, dit-on, la vit éperonner un navire et s''exclama que ses hommes s''étaient transformés en femmes et ses femmes en hommes. Son origine même semblait un croisement de mondes.', '["Artémise d''Halicarnasse","Phérétimé de Cyrène","Atossa de Perse","Laodice de Carie"]'::jsonb, 'Artémise d''Halicarnasse', 'Artémise Ire d''Halicarnasse, reine de Carie et vassale de Xerxès, commanda cinq navires à Salamine. Elle fut la seule à déconseiller l''engagement naval à Xerxès ; pendant la bataille, elle coula un navire allié pour s''échapper, trompant les Athéniens qui la poursuivaient.', TRUE),
('daily', 'hard', 'grecque', 'free', 'Quel nom portait le détroit entre l''Asie et l''Europe que Xerxès franchit sur ses ponts de bateaux en 480 av. J.-C. ?', 'Les anciens l''appelaient la frontière entre deux mondes, le lieu où la terre ferme cédait à un bras d''eau chargé de vents capricieux. Des villes prospères gardaient ses rives depuis des siècles, témoins de tous les passages et de toutes les ambitions. Franchir ce seuil liquide n''était pas seulement un acte militaire — c''était une déclaration cosmique.', NULL, 'Hellespont', 'L''Hellespont (actuel détroit des Dardanelles) fut franchi par Xerxès en 480 av. J.-C. grâce à deux ponts de bateaux consécutifs. Hérodote estime que le passage de l''armée prit sept jours et sept nuits.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Quel orateur athénien du IVe siècle prononça les Philippiques pour alerter la cité sur la menace macédonienne croissante ?', 'Ses mots tombaient sur l''Ecclesia comme des pierres dans un lac calme — chaque discours envoyait des cercles jusqu''aux bords de la cité. On raconte qu''il s''entraînait avec des galets dans la bouche pour forger une éloquence capable de réveiller un peuple endormi.', '["Isocrate","Eschine","Démosthène","Hypéride"]'::jsonb, 'Démosthène', 'Démosthène (384-322 av. J.-C.) prononça les Philippiques (351-341 av. J.-C.), série de discours politiques devant l''Ecclesia pour mobiliser Athènes contre la puissance montante de Philippe II de Macédoine.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Zénon d''Élée formula un paradoxe montrant qu''une flèche en vol est en réalité immobile à chaque instant. Quel argument central emploie-t-il ?', 'Alors qu''on armait les arcs et que les flèches sifflaient sur les champs de bataille grecs, un philosophe prétendait que chaque projectile était, dans l''absolu, aussi fixe qu''une pierre. Les généraux n''en crurent rien ; les logiciens ne surent pas le réfuter.', '["Une flèche parcourt une infinité de distances et s''épuise donc avant d''arriver","À chaque instant, la flèche occupe un espace égal à elle-même, donc elle est au repos à cet instant","Le temps n''étant pas divisible, la flèche saute d''un point à l''autre sans traverser l''espace intermédiaire","La flèche se déplace plus vite que la perception du mouvement, créant l''illusion de la continuité"]'::jsonb, 'À chaque instant, la flèche occupe un espace égal à elle-même, donc elle est au repos à cet instant', 'Dans le paradoxe de la flèche, Zénon soutient qu''à tout instant « maintenant » la flèche occupe un espace exactement égal à elle-même : elle est donc immobile à cet instant. Puisque le temps n''est que la somme de ces instants, la flèche est toujours immobile.', TRUE),
('daily', 'hard', 'grecque', 'free', 'Épictète était esclave avant de devenir philosophe. Dans quelle ville d''Asie Mineure est-il né ?', 'Né dans les fers, vendu comme bien meuble, il entendit un jour son maître lui briser la jambe pour en éprouver la résistance. Il resta impassible. Cette impassibilité, il en fit toute sa philosophie : seul l''intérieur nous appartient, jamais les chaînes du monde.', NULL, 'Hiérapolis', 'Épictète (vers 50-135 apr. J.-C.) naquit à Hiérapolis en Phrygie (actuelle Turquie). Esclave à Rome, il fut affranchi et fonda à Nicopolis une école dont les leçons furent consignées par Arrien dans le Manuel et les Entretiens.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Démocrite distinguait deux types de connaissance : l''une « bâtarde », l''autre « légitime ». À quoi correspondait la connaissance « légitime » ?', 'Le philosophe rieur avait compris que nos yeux et nos oreilles nous mentent : ce qu''ils rapportent n''est qu''une ombre de la réalité profonde. Pour atteindre la vérité, il fallait transcender les sens et plonger dans un autre mode de saisie du réel.', '["La connaissance par les sens, car ils touchent le monde directement","La connaissance par la raison, atteignant la structure atomique cachée","La connaissance révélée par les dieux dans les songes","La connaissance transmise oralement par les maîtres à leurs disciples"]'::jsonb, 'La connaissance par la raison, atteignant la structure atomique cachée', 'Démocrite distinguait la gnôsis skotiè (connaissance bâtarde/obscure), issue des sens — qui ne perçoivent que les effets macroscopiques —, de la gnôsis gnèsiè (connaissance légitime/authentique), propre à la raison seule, capable de saisir la réalité atomique invisible.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Hipparque inventa un système de coordonnées célestes fondamental : lequel ?', 'Pour qu''une étoile ne soit jamais perdue dans l''immensité du ciel, il fallait inventer un langage universel, deux nombres capables de la fixer pour l''éternité. Ce savant de Rhodes posa les jalons d''une grammaire céleste que les astronomes utilisent encore.', '["Les coordonnées écliptiques (longitude et latitude célestes)","Les coordonnées galactiques polaires","Le système azimutal local","Les coordonnées équatoriales en déclinaison et ascension droite"]'::jsonb, 'Les coordonnées écliptiques (longitude et latitude célestes)', 'Hipparque généralisa l''usage des coordonnées écliptiques (longitude et latitude par rapport à l''écliptique) pour cataloguer les étoiles, système inspiré des Babyloniens mais formalisé mathématiquement et appliqué systématiquement pour la première fois par lui.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'La théurgie, telle que développée par Jamblique au IIIe siècle, se distinguait de la simple philosophie par un principe clef. Lequel ?', 'Le philosophe pouvait contempler le divin par la raison seule — c''était le chemin des sages depuis des générations. Mais certains affirmaient que la contemplation ne suffisait pas : il fallait agir, accomplir des rites précis, convoquer des présences invisibles. La frontière entre philosophie et magie devenait poreuse.', '["La raison pure suffit à unir l''âme aux dieux sans rite extérieur","Les rites matériels sont indispensables car les dieux répondent aux actes, non aux seules pensées","Seul le sacrifice sanglant permet d''atteindre l''Un plotinien","La connaissance des noms divins secrets remplace tout rite corporel"]'::jsonb, 'Les rites matériels sont indispensables car les dieux répondent aux actes, non aux seules pensées', 'Jamblique (De Mysteriis, IIIe s.) oppose la théurgie à la théologie pure : les rites — pierres, herbes, sons, gestes — sont nécessaires car ils actionnent des sympathies cosmiques que la pensée seule ne peut mobiliser. C''est une rupture avec le néoplatonisme de Plotin.', TRUE),
('daily', 'hard', 'grecque', 'free', 'Quel sanctuaire d''Asclépios, dans le Péloponnèse, était considéré comme le plus grand centre d''incubation du monde grec, célèbre aussi pour son théâtre aux acoustiques parfaites ?', 'Des malades venaient de tout le bassin méditerranéen pour y dormir sur la peau sacrée. Le tholos mystérieux du sanctuaire, aux labyrinthes souterrains, intriguait encore les archéologues du XXe siècle. La guérison du corps et la beauté de la pierre semblaient ici inséparables.', NULL, 'Épidaure', 'Le sanctuaire d''Asclépios à Épidaure (Argolide) est le plus grand Asclépeion connu. Son théâtre (IVe s. av. J.-C., architecte Polyclète le Jeune) est réputé pour son acoustique exceptionnelle. Le tholos (rotonde) comportait un couloir souterrain en spirale dont la fonction reste discutée.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Dans les Mystères dionysiaques, le rituel appelé ''omophagie'' désignait quel acte précis ?', 'Les initiés en furie mimaient le sort d''un être divin, déchiqueté avant d''être reconstitué. L''acte central du rite brouillait la frontière entre le chasseur et le gibier, entre l''humain et le divin. Platon et d''autres philosophes y voyaient une image cryptée du destin de l''âme.', '["Boire du vin non coupé d''eau en l''honneur du dieu","Dévorer la chair crue d''un animal sacrifié","Porter le masque du dieu et prononcer ses paroles sacrées","Brûler des effigies de blé pour symboliser la renaissance végétale"]'::jsonb, 'Dévorer la chair crue d''un animal sacrifié', 'L''omophagie (ômos, cru ; phagein, manger) est attestée dans les rites dionysiaques : les ménades dévoraient la chair crue d''un animal — souvent un faon ou un taureau — mimant le démembrement de Dionysos Zagreus par les Titans. Diodore et Plutarque en témoignent.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Myron sculpta vers 450 av. J.-C. une statue représentant un athlète au moment précis du lancer. Quel sport pratique cet athlète ?', 'L''œuvre originale en bronze a disparu, mais des copies romaines en marbre ont traversé les siècles. Ce moment figé défie la physique : l''artiste captura un instant impossible, suspendu entre élan et libération, comme si le temps lui-même avait obéi au ciseau.', '["Le javelot","Le marteau","Le disque","La fronde"]'::jsonb, 'Le disque', 'Le Discobole (Diskobolos) de Myron, vers 450 av. J.-C., représente un lanceur de disque en pleine rotation, bras tendu en arrière. L''original en bronze est perdu ; on le connaît par des copies romaines en marbre.', TRUE),
('daily', 'hard', 'grecque', 'free', 'Quel auteur comique grec du IVe–IIIe siècle av. J.-C., représentant de la ''comédie nouvelle'', est l''auteur du Dyscolos (Le Bourru) ?', 'Ses pièces avaient presque toutes disparu, réduites à des fragments épars pendant deux millénaires. Puis un papyrus découvert en Égypte au XXe siècle rendit à la littérature grecque une voix perdue, celle d''un maître des caractères humains et des intrigues de mœurs.', NULL, 'Ménandre', 'Ménandre (v. 342–290 av. J.-C.) est le maître de la comédie nouvelle athénienne. Le Dyscolos, sa seule pièce quasi intégrale, a été retrouvé sur le papyrus Bodmer en 1952 en Égypte.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Quel est le terme grec désignant l''espace circulaire au sol, devant la scène, où évoluait le chœur dans le théâtre antique ?', 'Avant même que la scène bâtie existe, il y avait ce cercle de terre battue, ce lieu de rotation et de chant collectif. Certains y voient l''espace originel du rituel dionysiaque, là où la frontière entre mortel et divin se faisait la plus mince.', '["Le proskénion","L''orchestra","La skènè","Le parodos"]'::jsonb, 'L''orchestra', 'L''orchestra (du grec orkheisthai, danser) est l''espace circulaire où évoluait le chœur. La skènè est le bâtiment de scène, le proskénion la façade avant, le parodos l''entrée latérale du chœur.', TRUE),
('daily', 'hard', 'grecque', 'free', 'Comment s''appelait l''impôt spécifique que les métèques devaient verser annuellement à Athènes pour avoir le droit de résider dans la cité ?', 'Chaque année, à date fixe, le résident étranger se présentait devant le magistrat compétent, accompagné de son garant citoyen. Sans ce versement, sa présence devenait illégale et ses biens confiscables. Un tribut modeste — mais qui rappelait à chaque paiement que la cité n''était pas la sienne.', NULL, 'Métoikion', 'Le métoikion était l''impôt annuel de résidence dû par les métèques : 12 drachmes pour un homme, 6 pour une femme indépendante. Son non-paiement exposait au statut d''esclave vendu au profit de l''État.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Quelle était la condition juridique des femmes citoyennes athéniennes (astai) en matière de contrats et de propriété ?', 'Elle pouvait filer la laine, diriger l''oikos en l''absence de son époux, veiller aux rites domestiques — et pourtant, nulle tablette de contrat ne portait son nom. La cité lui reconnaissait une naissance et une descendance légitimes, mais refusait de lui accorder la main qu''elle aurait dû tendre pour signer.', '["Elle pouvait contracter librement jusqu''à une valeur d''un médimne d''orge","Elle ne pouvait contracter ou posséder des biens que sous tutelle masculine (kyrios)","Elle était pleinement capable juridiquement mais exclue des seules charges publiques","Elle pouvait posséder des biens fonciers mais pas mobiliers"]'::jsonb, 'Elle ne pouvait contracter ou posséder des biens que sous tutelle masculine (kyrios)', 'À Athènes, toute femme citoyenne était placée sous la tutelle légale (kyria) d''un homme — père, époux ou frère — sans lequel elle ne pouvait pas conclure de contrat au-delà d''une valeur symbolique. Cette incapacité juridique était totale dans la sphère publique et commerciale.', TRUE),
('daily', 'hard', 'grecque', 'qcm', 'Lors du siège de Rhodes par Démétrios Poliorcète (305–304 av. J.-C.), quel engin de siège monumental lui valut son surnom ?', 'On dit que jamais encore on n''avait vu pareille construction rouler vers une muraille. Des centaines d''hommes tiraient sur des cordages, faisant avancer une tour de neuf étages bardée de métal, protégée par des peaux mouillées contre les projectiles enflammés. Les Rhodiens résistèrent, mais le monde grec retint le nom de celui qui avait osé bâtir une telle bête.', '["L''arète (bélier géant)","L''hélépole (preneur de ville)","Le sambuca (échelle d''assaut navale)","Le gastraphète (arc-ventre)"]'::jsonb, 'L''hélépole (preneur de ville)', 'L''hélépole (« preneur de villes ») était une immense tour de siège mobile, construite pour Démétrios Poliorcète par l''ingénieur Épimacos d''Athènes. Lors du siège de Rhodes, elle atteignait environ 40 mètres de haut sur neuf niveaux. C''est cet engin qui valut à Démétrios son surnom de ''Poliorcète'' (assiégeur de villes).', TRUE);
